const f = $input.first().json;
const num = (v) => (v === '' || v === null || v === undefined ? null : Number(v));
const pair = (a, b, scale) => {
  const lo = num(a);
  const hi = num(b);
  if (lo === null && hi === null) return null;
  return [lo === null ? null : lo * scale, hi === null ? null : hi * scale];
};
const ranges = {
  market_cap_cr: pair(f.mcap_min, f.mcap_max, 1),
  revenue_cr: pair(f.rev_min, f.rev_max, 1),
  ebitda_margin: pair(f.margin_min, f.margin_max, 0.01),
  roce: pair(f.roce_min, f.roce_max, 0.01)
};
const overrides = {};
for (const [key, value] of Object.entries(ranges)) {
  if (value) overrides[key] = value;
}
const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
if (list(f.include).length) overrides.include = list(f.include);
if (list(f.exclude).length) overrides.exclude = list(f.exclude);
const ticker = String(f.ticker || '').trim();
const email = String(f.email || '').trim();
return [{ json: { ticker, email, screen_body: { ticker, overrides } } }];

const group = (list) => {
  const by = {};
  for (const e of list || []) { (by[e.reason] = by[e.reason] || []).push(e.symbol); }
  return Object.entries(by).map(([r, s]) => '- ' + r + ': ' + s.join(', ')).join('\n');
};
const s = $input.first().json;
let problem = '';
if (s.error) {
  problem = String(s.error);
} else if (!Array.isArray(s.candidates) || s.candidates.length === 0) {
  problem = 'No companies in the same industry passed the filters.\n\nRemoved by the screen:\n' + (group(s.excluded) || '- none') + '\n\nLoosen the ranges, or leave them blank for Auto.';
}
return [{ json: { ...s, problem } }];

const s = $input.first().json;
const rubric = [
  'You compare a CANDIDATE company to a TARGET company for use in a trading-comparables (comps) analysis.',
  'Score the candidate on each criterion from 0 to 3, or null if the business descriptions do not contain enough information to judge.',
  'Scale: 3 = near-identical, 2 = substantial overlap, 1 = partial overlap, 0 = no overlap or opposite.',
  'Criteria:',
  '- product: do they sell the same kinds of products or services (category overlap)?',
  '- customer_channel: same kind of customers and routes to market (consumer vs business, retail vs institutional, distributors vs e-commerce)?',
  '- business_model: similar business model and revenue mix (branded vs contract, single product vs diversified, recurring vs one-off)?',
  '- value_drivers: do the same things move earnings (raw material costs, regulation, seasonality, commodity exposure)?',
  '- operating_model: similar operating model (manufacturer, asset-light, trader, mixed)?',
  '- geography_positioning: similar geographic mix and market positioning (domestic vs export, premium vs mass)?',
  'Rules:',
  '- Use only the two descriptions provided. If a criterion cannot be judged from them, return null, not 0.',
  '- Give a one-line evidence note per criterion quoting or paraphrasing the descriptions.',
  '- Also give "reason": one sentence on why this candidate is or is not a fair comp.',
  '- Also give "mismatch_note": name any criterion where the candidate clearly differs from the target and say whether it likely affects the valuation multiple. Use an empty string if there is no meaningful mismatch.',
  'Return ONLY a JSON object of this shape:',
  '{"scores":{"product":{"score":0,"evidence":""},"customer_channel":{"score":0,"evidence":""},"business_model":{"score":0,"evidence":""},"value_drivers":{"score":0,"evidence":""},"operating_model":{"score":0,"evidence":""},"geography_positioning":{"score":0,"evidence":""}},"reason":"","mismatch_note":""}'
].join('\n');
const describe = (p) => p.summary || p.name || p.symbol;
return s.candidates.map((c) => ({
  json: {
    symbol: c.symbol,
    profile: c,
    payload: {
      model: 'openai/gpt-oss-120b',
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: rubric },
        { role: 'user', content: 'TARGET (' + s.target.symbol + '):\n' + describe(s.target) + '\n\nCANDIDATE (' + c.symbol + ', ' + (c.name || '') + '):\n' + describe(c) }
      ]
    }
  }
}));

const prompts = $('Build Score Prompts').all();
const answers = $input.all();
const scored = answers.map((item, i) => {
  let llm = null;
  let score_error = '';
  try {
    llm = JSON.parse(item.json.choices[0].message.content);
  } catch (e) {
    score_error = item.json.error ? String(item.json.error.message || item.json.error) : 'model reply was not valid JSON';
  }
  return { profile: prompts[i].json.profile, llm, score_error };
});
return [{ json: { target: $('Check Screen').first().json.target, scored } }];

const group = (list) => {
  const by = {};
  for (const e of list || []) { (by[e.reason] = by[e.reason] || []).push(e.symbol); }
  return Object.entries(by).map(([r, s]) => '- ' + r + ': ' + s.join(', ')).join('\n');
};
const r = $input.first().json;
const shortlist = r.shortlist || [];
const rejectedAll = r.rejected || [];
const isUnscored = (x) => String(x.reason).startsWith('unscored');
const unscored = rejectedAll.filter(isUnscored);
const rejected = rejectedAll.filter((x) => !isUnscored(x)).map((x) => '- ' + x.symbol + ': ' + x.reason).join('\n');
const screen = $('Check Screen').first().json;
const target = screen.target.symbol;
const too_few = shortlist.length < 3;
const limitHit = unscored.length > 0 && unscored.length * 2 >= rejectedAll.length + shortlist.length;
let message = 'Only ' + shortlist.length + ' of the screened companies were similar enough to ' + target + ' (at least 3 are needed for meaningful comps).\n';
if (limitHit) {
  message += '\n' + unscored.length + ' companies could not be scored by the AI, most likely because the free Groq daily limit was reached. Try again later; loosening the ranges will not help.\n';
} else if (unscored.length) {
  message += '\n' + unscored.length + ' companies could not be scored by the AI (' + unscored.map((x) => x.symbol).join(', ') + '). Run again to retry them.\n';
}
message += '\nScored but not shortlisted:\n' + (rejected || '- none') + '\n\nRemoved by the screen:\n' + (group(screen.excluded) || '- none') + '\n\nTry loosening the ranges or adding tickers under include.';
return [{ json: { ...r, too_few, message } }];

const r = $input.first().json;
return [{ json: { approval_body: {
  target: $('Check Screen').first().json.target,
  shortlist: r.shortlist,
  email: $('Build Screen Request').first().json.email,
  resume_url: $execution.resumeUrl
} } }];

const chosen = $input.first().json.body.chosen;
const target = $('Check Screen').first().json.target;
const peers = $('Rank Peers').first().json.shortlist.filter((p) => chosen.includes(p.profile.symbol));
return [{ json: { chosen, facts_body: { target, peers: peers.map((p) => p.profile) } } }];

let commentary = { summary: 'AI commentary was unavailable for this run.', per_peer: {} };
try {
  const parsed = JSON.parse($input.first().json.choices[0].message.content);
  if (parsed && typeof parsed.summary === 'string') {
    commentary = { summary: parsed.summary, per_peer: parsed.per_peer || {} };
  }
} catch (e) {
  commentary = { summary: 'AI commentary was unavailable for this run.', per_peer: {} };
}
const screen = $('Check Screen').first().json;
const rank = $('Rank Peers').first().json;
const rejected = (rank.rejected || []).map((r) => ({ symbol: r.symbol, reason: r.reason }));
const build_body = {
  id: $('Create Approval Request').first().json.id,
  commentary,
  sources: {
    criteria_lines: screen.criteria_lines || [],
    excluded: [...(screen.excluded || []), ...rejected],
    dropped_criteria: screen.dropped_criteria || []
  }
};
return [{ json: { build_body } }];

const f = $input.first().json;
const target = $('Check Screen').first().json.target;
const chosen = $('Build Facts Request').first().json.chosen;
const peers = $('Rank Peers').first().json.shortlist.filter((p) => chosen.includes(p.profile.symbol));
const data = {
  target: { symbol: target.symbol, name: target.name, ...f.target },
  peers: peers.map((p) => ({ symbol: p.profile.symbol, name: p.profile.name, similarity: p.similarity, ...f.peers[p.profile.symbol] })),
  peer_statistics_used_in_sheet: f.stats,
  outliers_removed_from_statistics: f.trimmed
};
const system = [
  'You write short valuation commentary for an investment banking trading comps sheet.',
  'Use ONLY the numbers provided. Never invent or recompute figures. If a value is null, say it is not available.',
  'When you describe the peer range or typical level, quote peer_statistics_used_in_sheet (min, median, max) exactly. Do not make up ranges.',
  'Return ONLY JSON: {"summary":"2 to 3 sentences on how the target trades versus the peer set","per_peer":{"SYMBOL":"one sentence on that peer"}}',
  'Include every peer symbol in per_peer. Plain text, no markdown.'
].join('\n');
return [{ json: { chosen, payload: { model: 'openai/gpt-oss-120b', temperature: 0, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(data) }] } } }];

